// Accepts a Gmail Trigger item (simple: false) or the sample request from the test path.
// isTest = the built-in sample (uses a sample Shopify order).
// dryRun = anything that is not a production run of the active workflow (n8n reports editor runs as 'test'):
// never refunds, never emails a customer.
const settings = $('Store settings').first().json;

return $input.all().map((item) => {
  const j = item.json;
  const fromAddress = (j.from?.value?.[0]?.address || j.fromEmail || '').toLowerCase().trim();
  const fromName = j.from?.value?.[0]?.name || j.fromName || '';
  const body = (j.text || j.body || '').toString().trim();
  const isTest = Boolean(j.isTest);

  return {
    json: {
      messageId: j.id || j.messageId || null,
      // The return window is counted from when we received the email, not the sender's Date header.
      receivedAt: new Date().toISOString(),
      fromAddress,
      fromName,
      subject: j.subject || '(no subject)',
      // Cap what goes to the model. Return requests are short; quoted threads are not.
      requestText: body.slice(0, Number(settings.maxEmailChars) || 5000),
      isTest,
      dryRun: isTest || $execution.mode !== 'production',
    },
  };
});

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "customerName": {
      "type": "string",
      "description": "Name the customer signs with, else empty"
    },
    "orderNumber": {
      "type": "string",
      "description": "Order number digits only, e.g. 1047 for '#1047'. Empty if none is given."
    },
    "wholeOrder": {
      "type": "boolean",
      "description": "True only if they clearly want to return everything in the order"
    },
    "items": {
      "type": "array",
      "description": "Each product they want to return, in their words",
      "items": {
        "type": "object",
        "properties": {
          "description": {
            "type": "string"
          },
          "quantity": {
            "type": "integer"
          }
        },
        "required": [
          "description",
          "quantity"
        ]
      }
    },
    "reason": {
      "type": "string",
      "enum": [
        "damaged",
        "defective",
        "wrong_item",
        "not_as_described",
        "size_fit",
        "changed_mind",
        "not_received",
        "other"
      ]
    },
    "requestedResolution": {
      "type": "string",
      "enum": [
        "refund",
        "exchange",
        "store_credit",
        "unclear"
      ]
    },
    "summary": {
      "type": "string",
      "description": "One neutral sentence for staff"
    }
  },
  "required": [
    "orderNumber",
    "wholeOrder",
    "items",
    "reason",
    "requestedResolution",
    "summary"
  ]
}

