// No order number in the email: ask for it. Nothing is looked up.
const s = $('Store settings').first().json;
const req = $('Normalise request').first().json;
const ask = $input.first().json.output || {};
const firstName = (ask.customerName || req.fromName || '').split(' ')[0] || 'there';
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{ json: {
  slackText: `:mag: *Return request without an order number*${req.dryRun ? ' [TEST]' : ''} from ${esc(req.fromName || req.fromAddress)} &lt;${esc(req.fromAddress)}&gt;. Asked them for it.\n> ${esc(ask.summary || '')}`,
  replyText: String(s.replyAskOrderTemplate).replaceAll('{{firstName}}', firstName).replaceAll('{{storeName}}', s.storeName),
  sendReply: true,
  log: { received_at: req.receivedAt, from: req.fromAddress, order: '', reason: ask.reason || '', resolution: ask.requestedResolution || '',
         route: 'ask_order', decision: 'ask_order', amount: '', currency: '', refund_id: '', approved_by: '', notes: '' },
} }];

// GraphQL lookup by order name. Shopify's search is fuzzy; the policy node insists on an exact match.
const n = String($input.first().json.output.orderNumber).replace(/\D/g, '');
return [{ json: { isTest: $('Normalise request').first().json.isTest, shopifyRequest: {
  query: `query FindOrder($q: String!) {
  orders(first: 5, query: $q) {
    nodes {
      id name email createdAt cancelledAt displayFinancialStatus
      fulfillments(first: 10) { status createdAt deliveredAt }
      lineItems(first: 100) { nodes { id name title sku quantity refundableQuantity currentQuantity unfulfilledQuantity isGiftCard product { tags } } }
    }
  }
}`,
  variables: { q: `name:#${n} OR name:${n}` },
} } }];

// Test runs never call Shopify. This is the shape the real lookup returns.
const iso = (daysAgo) => new Date(Date.now() - daysAgo * 864e5).toISOString();
return [{ json: { data: { orders: { nodes: [{
  id: 'gid://shopify/Order/5550001047', name: '#1047', email: 'user@example.com',
  createdAt: iso(16), cancelledAt: null, displayFinancialStatus: 'PAID',
  fulfillments: [{ status: 'SUCCESS', createdAt: iso(14), deliveredAt: iso(11) }],
  lineItems: { nodes: [
    { id: 'gid://shopify/LineItem/901', name: 'Linen Overshirt - M', title: 'Linen Overshirt', sku: 'LO-M', quantity: 1, refundableQuantity: 1, currentQuantity: 1, unfulfilledQuantity: 0, isGiftCard: false, product: { tags: ['tops'] } },
    { id: 'gid://shopify/LineItem/902', name: 'Canvas Tote', title: 'Canvas Tote', sku: 'CT-1', quantity: 1, refundableQuantity: 1, currentQuantity: 1, unfulfilledQuantity: 0, isGiftCard: false, product: { tags: ['bags'] } },
    { id: 'gid://shopify/LineItem/903', name: 'Gift Card Sleeve', title: 'Gift Card Sleeve', sku: 'GS-1', quantity: 1, refundableQuantity: 1, currentQuantity: 1, unfulfilledQuantity: 0, isGiftCard: false, product: { tags: ['final-sale'] } },
  ] },
}] } } } }];

// RETURN POLICY: every eligibility decision is made here, in plain JavaScript you can audit.
// Claude only extracted the order number, items and reason. Nothing below asks the model anything.
const s = $('Store settings').first().json;
const req = $('Normalise request').first().json;
const ask = $('Extract return details').first().json.output || {};
const res = $input.first().json; // Shopify GraphQL response (or the sample order in test runs)

const DAY = 24 * 60 * 60 * 1000;
const csv = (v) => String(v || '').split(',').map((x) => x.trim().toLowerCase()).filter(Boolean);
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const DEFECT_REASONS = csv(s.defectReasons);          // reasons that are the store's fault
const FEE_REASONS = csv(s.restockingFeeReasons);      // reasons that carry a restocking fee
const FINAL_SALE_TAGS = csv(s.finalSaleTags);
const isDefect = DEFECT_REASONS.includes(ask.reason);

const firstName = (ask.customerName || req.fromName || '').split(' ')[0] || 'there';
const fill = (tpl, extra = {}) => Object.entries({ firstName, storeName: s.storeName, orderNumber: ask.orderNumber || '', ...extra })
  .reduce((t, [k, v]) => t.replaceAll(`{{${k}}}`, String(v)), String(tpl || ''));

const tag = req.dryRun ? ' [TEST]' : '';
const who = `${esc(req.fromName || req.fromAddress)} &lt;${esc(req.fromAddress)}&gt;`;
const summary = esc(ask.summary || '');
const baseLog = {
  received_at: req.receivedAt, from: req.fromAddress, order: ask.orderNumber ? `#${ask.orderNumber}` : '',
  reason: ask.reason || '', resolution: ask.requestedResolution || '', amount: '', currency: '', refund_id: '', approved_by: '',
};
const done = (route, slackText, replyKey, notes) => [{ json: {
  route, slackText, replyText: replyKey ? fill(s[replyKey]) : '', sendReply: Boolean(replyKey),
  log: { ...baseLog, route, decision: route, notes: notes || '' },
} }];

// ---- 0. The email must really come from the address in its From header (Gmail's own DMARC verdict).
// Skipped only for the built-in sample, which has no Gmail message.
if (!req.isTest) {
  const auth = $('Check sender (Gmail)').first().json;
  // Gmail puts its own Authentication-Results header first; anything below it could be forged by the sender.
  const verdict = ((auth.payload?.headers || []).find((h) => String(h.name).toLowerCase() === 'authentication-results') || {}).value || '';
  if (!/^\s*mx\.google\.com;/i.test(verdict) || !/\bdmarc=pass\b/i.test(verdict)) {
    return done('staff', `:lock: *Return request failed sender authentication*${tag}: ${who}. Gmail did not report DMARC pass, so the From address can't be trusted. Nothing was looked up. Reply personally if it is genuine.\n> ${summary}`, 'replyAckTemplate', 'sender_not_authenticated');
  }
}

// ---- 1. Find the order. Compare digits only, and insist on exactly one match.
const gqlErrors = res.errors || [];
if (gqlErrors.length) {
  const text = gqlErrors.map((e) => e.message).join('; ');
  const hint = /protected customer data|not approved to access|customer data/i.test(text)
    ? 'The app is not approved for protected customer data (the order email). Request access to the email field for the app.'
    : 'Check the app scopes: read_orders, read_all_orders, write_orders, read_products.';
  return done('staff', `:warning: *Shopify lookup failed*${tag} for ${who}: ${esc(text)}. ${hint}`, 'replyAckTemplate', 'shopify_lookup_error');
}
const digits = String(ask.orderNumber || '').replace(/\D/g, '');
const matches = (res.data?.orders?.nodes || []).filter((o) => String(o.name).replace(/\D/g, '') === digits);
if (matches.length > 1) {
  return done('staff', `:mag: *Return request matches ${matches.length} orders*${tag}: ${who} quoted ${esc(digits)} (${matches.map((o) => esc(o.name)).join(', ')}). Pick the right one by hand.\n> ${summary}`, 'replyAckTemplate', 'ambiguous_order');
}
const order = matches[0];
if (!order) {
  return done('not_found', `:mag: *Return request, order not found*${tag}: ${who} quoted order #${esc(digits)}. Asked them to check the number. (Orders older than 60 days need the read_all_orders scope.)\n> ${summary}`, 'replyAskOrderTemplate', 'order_not_found');
}

// ---- 2. The sender must be the person who placed the order.
const adminUrl = `https://admin.shopify.com/store/${String(s.shopDomain).replace('.myshopify.com', '')}/orders/${order.id.split('/').pop()}`;
const orderLink = `<${adminUrl}|${esc(order.name)}>`;
const staff = (why) => done('staff', `:raising_hand: *Return needs a person*${tag}: ${who}, ${orderLink}. ${esc(why)}\n> ${summary}`, 'replyAckTemplate', why);
if (!order.email) return staff('The order has no email address (placed with a phone number?), so ownership cannot be checked.');
if (String(order.email).toLowerCase() !== req.fromAddress) {
  return done('email_mismatch', `:lock: *Return request from a different email*${tag}: ${who} asked about ${orderLink}, which belongs to another address. Asked them to write from the address on the order. Nothing about the order was shared.`, 'replyWrongEmailTemplate', 'email_mismatch');
}

// ---- 3. Order-level stops: these always go to a person.
if (order.cancelledAt) return staff('The order is cancelled.');
if (!['PAID', 'PARTIALLY_REFUNDED'].includes(order.displayFinancialStatus)) return staff(`Payment status is ${order.displayFinancialStatus}, not PAID.`);
if (ask.reason === 'not_received') return staff('Customer says it never arrived. Check tracking or open a carrier claim.');
if (ask.requestedResolution !== 'refund') return staff(`Customer wants ${String(ask.requestedResolution || 'unclear').replace('_', ' ')}, not a refund. This workflow only automates refunds.`);

// ---- 4. Return window. Delivery date if the carrier reported one, else ship date plus a grace period.
const fulfils = (order.fulfillments || []).filter((f) => f.status === 'SUCCESS');
if (!fulfils.length) return staff('Nothing has shipped yet, so this is a cancellation, not a return.');
const delivered = fulfils.map((f) => f.deliveredAt).filter(Boolean).sort().pop();
const shipped = fulfils.map((f) => f.createdAt).filter(Boolean).sort().pop();
const start = delivered ? new Date(delivered) : new Date(new Date(shipped).getTime() + (Number(s.shippingGraceDays) || 0) * DAY);
const windowDays = isDefect ? Number(s.defectWindowDays) : Number(s.returnWindowDays);
const daysSince = Math.floor((new Date(req.receivedAt).getTime() - start.getTime()) / DAY);
const windowNote = `${daysSince} days since ${delivered ? 'delivery' : 'shipping (+grace)'}; window is ${windowDays} days${isDefect ? ' for faulty items' : ''}`;
if (daysSince > windowDays) {
  return done('ineligible', `:no_entry_sign: *Return outside the window*${tag}: ${who}, ${orderLink}. ${windowNote}. No refund was proposed. Reply personally if you want to make an exception.\n> ${summary}`, 'replyAckTemplate', `outside_window (${daysSince}d)`);
}

// ---- 5. Match what they want to return to shipped, non-gift-card line items.
const STOP = new Set(['the', 'and', 'for', 'one', 'two', 'with', 'from', 'this', 'that', 'item', 'items', 'order', 'size', 'pair', 'set', 'pack', 'piece', 'pieces', 'back', 'return', 'want', 'would', 'like', 'please', 'thanks', 'your', 'all']);
const words = (t) => String(t || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter((w) => w.length > 2 && !STOP.has(w));
// Shipped units still refundable. currentQuantity excludes units removed by order edits.
const returnable = (l) => Math.max(0, Math.min(l.refundableQuantity, l.currentQuantity ?? l.quantity) - (l.unfulfilledQuantity || 0));
const lines = (order.lineItems?.nodes || []).filter((l) => !l.isGiftCard && returnable(l) > 0);
const picks = [];
const flags = [];
if (ask.wholeOrder) {
  lines.forEach((l) => picks.push({ line: l, qty: returnable(l) }));
} else {
  for (const it of ask.items || []) {
    const w = words(it.description);
    let scored = lines.map((l) => {
      const lw = words(`${l.name} ${l.title} ${l.sku || ''}`);
      return { l, score: w.filter((x) => lw.includes(x)).length };
    }).filter((x) => x.score > 0).sort((a, b) => b.score - a.score);
    if (!scored.length && lines.length === 1 && (ask.items || []).length === 1) scored = [{ l: lines[0], score: 0 }];
    // No match, or a tie for the best score: we cannot tell which item they mean.
    if (!scored.length || (scored[1] && scored[1].score === scored[0].score)) {
      flags.push(`Could not match "${it.description}" to one returnable line item.`); continue;
    }
    const l = scored[0].l;
    const want = Math.max(1, Number(it.quantity) || 1);
    const prev = picks.find((p) => p.line.id === l.id);
    if (prev) prev.qty += want; else picks.push({ line: l, qty: want });
  }
  for (const p of picks) {
    if (p.qty > returnable(p.line)) flags.push(`Asked for ${p.qty} × ${p.line.name}, only ${returnable(p.line)} returnable.`);
  }
}
if (flags.length || !picks.length) return staff(flags.join(' ') || 'No returnable items matched the request.');

// ---- 6. Final-sale items are refundable only when faulty.
const isFinal = (p) => (p.line.product?.tags || []).some((t) => FINAL_SALE_TAGS.includes(String(t).toLowerCase()));
const finalSale = isDefect ? [] : picks.filter(isFinal);
if (finalSale.length) {
  const rest = picks.filter((p) => !isFinal(p));
  // Named a final-sale item, or nothing else is left: no refund is proposed.
  if (!ask.wholeOrder || !rest.length) {
    return done('ineligible', `:no_entry_sign: *Final-sale item*${tag}: ${who}, ${orderLink}. ${finalSale.map((p) => esc(p.line.name)).join(', ')} tagged final sale and the reason is "${esc(ask.reason)}". No refund was proposed.\n> ${summary}`, 'replyAckTemplate', 'final_sale');
  }
  // Returning the whole order: refund the rest and tell the manager what was left out.
  flags.push(`Left out final-sale: ${finalSale.map((p) => p.line.name).join(', ')}.`);
  picks.splice(0, picks.length, ...rest);
}

// ---- 7. Eligible: hand the exact lines to Shopify's refund calculator, then to a manager.
const restock = s.restockType === 'RETURN' && s.restockLocationId ? 'RETURN' : 'NO_RESTOCK';
if (s.restockType === 'RETURN' && restock !== 'RETURN') flags.push('restockType is RETURN but restockLocationId is empty, so stock will not be restocked.');

return [{ json: {
  route: 'approval',
  orderId: order.id,
  orderName: order.name,
  orderLink,
  adminUrl,
  who,
  firstName,
  windowNote,
  reason: ask.reason,
  summary,
  isDefect,
  refundShipping: isDefect && Boolean(s.refundShippingWhenFaulty),
  feePercent: FEE_REASONS.includes(ask.reason) ? Math.max(0, Math.min(100, Number(s.restockingFeePercent) || 0)) : 0,
  notes: flags.map(esc),
  refundLineItems: picks.map((p) => ({
    lineItemId: p.line.id,
    quantity: p.qty,
    restockType: restock,
    ...(restock === 'RETURN' ? { locationId: s.restockLocationId } : {}),
  })),
  lineSummary: picks.map((p) => `${p.qty} × ${esc(p.line.name)}`),
  log: { ...baseLog, order: order.name, route: 'approval', decision: 'pending_approval', notes: flags.join(' ') },
} }];

// Ask Shopify to calculate the refund for exactly these lines (tax, discounts, shipping included).
const p = $input.first().json;
return [{ json: { isTest: $('Normalise request').first().json.isTest, shopifyRequest: {
  query: `query CalculateRefund($id: ID!, $lines: [RefundLineItemInput!], $ship: Boolean) {
  order(id: $id) {
    suggestedRefund(refundLineItems: $lines, refundShipping: $ship) {
      amountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
      suggestedTransactions {
        gateway formattedGateway kind
        parentTransaction { id }
        amountSet { shopMoney { amount currencyCode } }
        maximumRefundableSet { shopMoney { amount currencyCode } }
      }
    }
  }
}`,
  variables: { id: p.orderId, lines: p.refundLineItems, ship: p.refundShipping },
} } }];

// Test runs never call Shopify. Shape of order.suggestedRefund for one 68.00 item paid by card.
return [{ json: { data: { order: { suggestedRefund: {
  amountSet: { shopMoney: { amount: '68.0', currencyCode: 'USD' }, presentmentMoney: { amount: '68.0', currencyCode: 'USD' } },
  suggestedTransactions: [{
    gateway: 'shopify_payments', formattedGateway: 'Shopify Payments', kind: 'SUGGESTED_REFUND',
    parentTransaction: { id: 'gid://shopify/OrderTransaction/7001' },
    amountSet: { shopMoney: { amount: '68.0', currencyCode: 'USD' } },
    maximumRefundableSet: { shopMoney: { amount: '92.0', currencyCode: 'USD' } },
  }],
} } } } }];

// Turns Shopify's own refund calculation into (a) the Slack approval message and (b) the exact
// refundCreate mutation that will run if the manager approves. Money comes from Shopify, not the model.
const s = $('Store settings').first().json;
const req = $('Normalise request').first().json;
const p = $('Apply return policy').first().json;
const res = $input.first().json;

const tag = req.dryRun ? ' [TEST]' : '';
const staff = (why) => [{ json: {
  route: 'staff',
  slackText: `:raising_hand: *Return needs a person*${tag}: ${p.who}, ${p.orderLink}. ${String(why).replace(/</g, '&lt;')}\n> ${p.summary}`,
  replyText: String(s.replyAckTemplate).replaceAll('{{firstName}}', p.firstName).replaceAll('{{storeName}}', s.storeName).replaceAll('{{orderNumber}}', p.orderName.replace('#', '')),
  sendReply: true,
  log: { ...p.log, decision: 'staff', notes: why },
} }];

if ((res.errors || []).length) return staff(`Shopify refund calculation failed: ${res.errors.map((e) => e.message).join('; ')}`);
const sr = res.data?.order?.suggestedRefund;
if (!sr) return staff('Shopify returned no refund calculation for this order.');

const shopCur = sr.amountSet.shopMoney.currencyCode;
const presCur = sr.amountSet.presentmentMoney.currencyCode;
// Multi-currency refunds need a person: transaction amounts and currencies must line up exactly.
if (shopCur !== presCur) return staff(`Order was paid in ${presCur} but the shop currency is ${shopCur}. Refund it manually in Shopify.`);

let digits = 2;
try { digits = new Intl.NumberFormat('en', { style: 'currency', currency: shopCur }).resolvedOptions().maximumFractionDigits; } catch (e) { /* keep 2 */ }
const unit = 10 ** digits;
const toMinor = (v) => Math.round(Number(v) * unit);
const fmt = (minor) => (minor / unit).toFixed(digits);

const suggestedMinor = toMinor(sr.amountSet.shopMoney.amount);
const txs = (sr.suggestedTransactions || []).filter((t) => toMinor(t.amountSet.shopMoney.amount) > 0);
if (suggestedMinor <= 0) return staff('Shopify calculates nothing left to refund on these items.');
if (!txs.length) return staff('Shopify suggested no payment to refund against (for example, a manual or external payment).');
// Only refund what Shopify allocated to real payments. If the two disagree (pending payments,
// store credit, partial payment), a person decides.
const baseMinor = txs.reduce((a, t) => a + toMinor(t.amountSet.shopMoney.amount), 0);
if (baseMinor !== suggestedMinor) return staff(`Shopify's refund total (${fmt(suggestedMinor)} ${shopCur}) differs from what it allocates to payments (${fmt(baseMinor)} ${shopCur}). Refund manually.`);
const feeMinor = Math.round(baseMinor * p.feePercent / 100);
const refundMinor = baseMinor - feeMinor;

// Spread the fee across payment methods in proportion; the last one absorbs rounding.
let left = refundMinor;
const transactions = txs.map((t, i) => {
  const own = toMinor(t.amountSet.shopMoney.amount);
  const share = i === txs.length - 1 ? left : Math.round(refundMinor * own / baseMinor);
  left -= share;
  // Never more than Shopify suggested for this payment, nor more than the gateway can refund.
  const cap = Math.min(own, toMinor(t.maximumRefundableSet?.shopMoney?.amount ?? t.amountSet.shopMoney.amount));
  return { orderId: p.orderId, gateway: t.gateway, kind: 'REFUND', parentId: t.parentTransaction?.id, amount: fmt(Math.min(share, cap)), _label: t.formattedGateway || t.gateway };
});
if (transactions.some((t) => !t.parentId)) return staff('A payment has no parent transaction to refund against.');
const totalMinor = transactions.reduce((a, t) => a + toMinor(t.amount), 0);
const notes = [...(p.notes || [])];
if (totalMinor !== refundMinor) notes.push(`A payment method caps the refund at ${fmt(totalMinor)} ${shopCur}.`);

// Same order + same email + same lines = same key, so a retry or a double click never refunds twice.
const raw = `${p.orderId}|${req.messageId || req.receivedAt}|${p.refundLineItems.map((l) => `${l.lineItemId}x${l.quantity}`).join(',')}`;
let h = 0; for (const ch of raw) h = (Math.imul(h, 31) + ch.charCodeAt(0)) | 0;
const idemKey = `amplence-return-${p.orderId.split('/').pop()}-${(h >>> 0).toString(16)}`;

const note = `Return: ${p.reason}${p.feePercent ? `, ${p.feePercent}% restocking fee` : ''}. Approved in Slack via n8n.`;
const input = {
  orderId: p.orderId,
  note,
  notify: Boolean(s.notifyCustomerFromShopify),
  refundLineItems: p.refundLineItems,
  ...(p.refundShipping ? { shipping: { fullRefund: true } } : {}),
  transactions: transactions.map(({ _label, ...t }) => t),
};
const mutation = `mutation ReturnRefund($input: RefundInput!) {
  refundCreate(input: $input) @idempotent(key: "${idemKey}") {
    refund { id totalRefundedSet { shopMoney { amount currencyCode } } }
    userErrors { field message }
  }
}`;

const money = (m) => `${fmt(m)} ${shopCur}`;
const approvalText = [
  `*Refund approval needed*${tag}`,
  `${p.who} | ${p.orderLink} | reason: *${p.reason}*`,
  `> ${p.summary}`,
  `*Items:* ${p.lineSummary.join(', ')}`,
  `*Shopify calculation:* ${money(suggestedMinor)}${p.refundShipping ? ' (includes shipping)' : ''}`,
  p.feePercent ? `*Restocking fee:* ${p.feePercent}% = ${money(feeMinor)}` : '',
  `*Refund if approved:* ${money(totalMinor)} to ${transactions.map((t) => `${t._label} ${t.amount}`).join(' + ')}`,
  `*Window:* ${p.windowNote}`,
  `*Restock:* ${p.refundLineItems[0].restockType}`,
  ...notes.map((n) => `:warning: ${n}`),
  '_This refunds money; it does not record a returned item. Approve once the item is back, or if you accept refunding first._',
  req.dryRun ? '_Test run: approving will NOT create a refund._' : '_Approving creates the refund in Shopify immediately._',
].filter(Boolean).join('\n');

return [{ json: {
  route: 'approval',
  approvalText,
  refundAmount: fmt(totalMinor),
  currency: shopCur,
  shopifyRequest: { query: mutation, variables: { input } },
  log: { ...p.log, amount: fmt(totalMinor), currency: shopCur },
} }];

// Declined in Slack, or nobody answered before the time limit. No money moves.
const s = $('Store settings').first().json;
const p = $('Apply return policy').first().json;
const a = $('Build approval message').first().json;
const req = $('Normalise request').first().json;
const d = $input.first().json.data || {};
const timedOut = d.approved !== false;
const by = d.responder ? (d.responder.name || d.responder.id || '') : '';
return [{ json: {
  slackText: timedOut
    ? `:hourglass: *Refund approval timed out*${req.dryRun ? ' [TEST]' : ''} for ${p.orderLink}. Nothing was refunded. Handle it manually: ${p.adminUrl}`
    : `:no_entry: *Refund declined*${req.dryRun ? ' [TEST]' : ''} for ${p.orderLink}${by ? ` by ${by}` : ''}. Nothing was refunded. Reply to ${p.who} personally with the reason.`,
  replyText: String(s.replyAckTemplate).replaceAll('{{firstName}}', p.firstName).replaceAll('{{storeName}}', s.storeName).replaceAll('{{orderNumber}}', p.orderName.replace('#', '')),
  sendReply: true,
  log: { ...a.log, decision: timedOut ? 'approval_timed_out' : 'declined', approved_by: by },
} }];

// Test runs stop here: this is what refundCreate returns, and no money moves.
const a = $('Build approval message').first().json;
return [{ json: { data: { refundCreate: {
  refund: { id: 'gid://shopify/Refund/TEST', totalRefundedSet: { shopMoney: { amount: a.refundAmount, currencyCode: a.currency } } },
  userErrors: [],
} } } }];

// Reads the refundCreate response (or the simulated one on test runs) and decides what everyone hears.
const s = $('Store settings').first().json;
const req = $('Normalise request').first().json;
const p = $('Apply return policy').first().json;
const a = $('Build approval message').first().json;
const res = $input.first().json;

const tag = req.dryRun ? ' [TEST]' : '';
const decision = $('Ask manager to approve refund').first().json.data || {};
const approvedBy = decision.responder ? (decision.responder.name || decision.responder.id || '') : '';
const fill = (tpl) => String(tpl || '')
  .replaceAll('{{firstName}}', p.firstName).replaceAll('{{storeName}}', s.storeName)
  .replaceAll('{{orderNumber}}', p.orderName.replace('#', '')).replaceAll('{{amount}}', a.refundAmount).replaceAll('{{currency}}', a.currency);

const problems = [
  ...(res.errors || []).map((e) => e.message),
  ...(res.data?.refundCreate?.userErrors || []).map((e) => `${(e.field || []).join('.')}: ${e.message}`),
];
const refund = res.data?.refundCreate?.refund;

if (problems.length || !refund) {
  return [{ json: {
    slackText: `:x: *Refund FAILED*${tag} for ${p.orderLink} (${a.refundAmount} ${a.currency}). Shopify said: ${problems.join('; ').replace(/</g, '&lt;') || 'no refund returned'}. Nothing was refunded; the customer has not been told. Refund manually: ${p.adminUrl}`,
    replyText: '', sendReply: false,
    log: { ...a.log, decision: 'refund_failed', approved_by: approvedBy, notes: problems.join('; ') },
  } }];
}

const refunded = refund.totalRefundedSet?.shopMoney;
return [{ json: {
  slackText: `:white_check_mark: *Refunded*${tag} ${refunded ? `${refunded.amount} ${refunded.currencyCode}` : `${a.refundAmount} ${a.currency}`} on ${p.orderLink} for ${p.who}${approvedBy ? `, approved by ${approvedBy}` : ''}.${req.dryRun ? ' (Simulated: no money moved.)' : ''}`,
  replyText: fill(s.replyRefundTemplate),
  sendReply: true,
  log: { ...a.log, decision: req.dryRun ? 'approved_simulated' : 'refunded', approved_by: approvedBy, refund_id: refund.id },
} }];

// A step failed (Claude, Gmail check, Shopify token or API after 3 tries). Tell staff; tell the customer nothing.
const req = $('Normalise request').first().json;
const err = $input.first().json.error || $input.first().json;
const msg = (typeof err === 'string' ? err : (err.message || JSON.stringify(err))).slice(0, 400).replace(/</g, '&lt;');
return [{ json: {
  slackText: `:warning: *Return workflow step failed*${req.dryRun ? ' [TEST]' : ''} while handling a return from ${req.fromAddress}: ${msg}\nIf this happened while creating a refund, check the order in Shopify before doing anything else.`,
  replyText: '', sendReply: false,
  log: { received_at: req.receivedAt, from: req.fromAddress, order: '', reason: '', resolution: '', route: 'error', decision: 'step_failed',
         amount: '', currency: '', refund_id: '', approved_by: '', notes: msg },
} }];

// Every path ends here with the same shape, so there is one Slack node, one reply node and one log node.
const req = $('Normalise request').first().json;
const o = $input.first().json;
return [{ json: {
  slackText: o.slackText,
  replyText: o.replyText || '',
  // Editor runs and emails without a Gmail message ID never get a reply.
  sendReply: Boolean(o.sendReply && o.replyText && !req.dryRun && req.messageId),
  messageId: req.messageId,
  log: o.log,
} }];
